rt_sin:
        BSR     rt_math__red
        CMP.L   #0,D2
        BEQ     .q0
        CMP.L   #1,D2
        BEQ     .q1
        CMP.L   #2,D2
        BEQ     .q2
.q3:
        BSR     rt_math__kcos
        JMP     fp_neg
.q0:
        BRA     rt_math__ksin
.q1:
        BRA     rt_math__kcos
.q2:
        BSR     rt_math__ksin
        JMP     fp_neg

