        CMP.L   #1,D2
        BEQ     .q1
        CMP.L   #2,D2
        BEQ     .q2
.q3:
        BRA     rt_math__ksin
.q0:
        BRA     rt_math__kcos
.q1:
        BSR     rt_math__ksin
        JMP     fp_neg
.q2:
        BSR     rt_math__kcos
        JMP     fp_neg

