        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_div
        UNLK    A6
        RTS
.odd:
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        JSR     fp_div
        JSR     fp_neg
        UNLK    A6
        RTS

; D0:D1 = x -> ATN(x)
rt_atn:
        LINK    A6,#-32
        CLR.L   -32(A6)                 ; slot 4: flags (bit 0 negative, 1 inverse, 2 pi/6)
        TST.L   D0
        BPL     .p
        BSET    #0,-29(A6)
.p:
        AND.L   #$7FFFFFFF,D0
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  rt_math__c_one,D2
        MOVE.L  rt_math__c_one+4,D3
        JSR     fp_cmp
        TST.L   D0
        BLE     .le1
        MOVE.L  rt_math__c_one,D0
        MOVE.L  rt_math__c_one+4,D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_div
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        BSET    #1,-29(A6)
.le1:
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  rt_math__c_tan_pi12,D2
        MOVE.L  rt_math__c_tan_pi12+4,D3
        JSR     fp_cmp
        TST.L   D0
        BLE     .small
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  rt_math__c_sqrt3,D2
        MOVE.L  rt_math__c_sqrt3+4,D3
        JSR     fp_mul
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  rt_math__c_one,D2
        MOVE.L  rt_math__c_one+4,D3
        JSR     fp_sub
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  rt_math__c_sqrt3,D2
        MOVE.L  rt_math__c_sqrt3+4,D3
        JSR     fp_add
        MOVE.L  D0,-24(A6)
        MOVE.L  D1,-20(A6)
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  -24(A6),D2
        MOVE.L  -20(A6),D3
        JSR     fp_div
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        BSET    #2,-29(A6)
.small:
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_mul
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        LEA     rt_math__atn_c,A0
        MOVEQ   #14,D0
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        BSR     rt_math__horner
        MOVE.L  D0,-24(A6)
        MOVE.L  D1,-20(A6)
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        JSR     fp_mul
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  -24(A6),D2
        MOVE.L  -20(A6),D3
        JSR     fp_mul
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        JSR     fp_add
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        BTST    #2,-29(A6)
        BEQ     .n6
        MOVE.L  rt_math__c_pio6,D0
        MOVE.L  rt_math__c_pio6+4,D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_add
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
.n6:
        BTST    #1,-29(A6)
        BEQ     .ni
        MOVE.L  rt_math__c_pio2,D0
        MOVE.L  rt_math__c_pio2+4,D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_sub
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
.ni:
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        BTST    #0,-29(A6)
        BEQ     .out
        JSR     fp_neg
.out:
        UNLK    A6
        RTS

; D0:D1 = x -> ASIN(x); |x| > 1: error 67
rt_asin:
        LINK    A6,#-16
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        AND.L   #$7FFFFFFF,D0
        MOVE.L  rt_math__c_one,D2
        MOVE.L  rt_math__c_one+4,D3
        JSR     fp_cmp
        TST.L   D0
        BGT     .err
        BLT     .in
        MOVE.L  rt_math__c_pio2,D0
        MOVE.L  rt_math__c_pio2+4,D1
        TST.L   -8(A6)
        BPL     .out
        JSR     fp_neg
.out:
        UNLK    A6
        RTS
.in:
        MOVE.L  rt_math__c_one,D0
        MOVE.L  rt_math__c_one+4,D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_sub
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  rt_math__c_one,D0
        MOVE.L  rt_math__c_one+4,D1
        MOVE.L  -8(A6),D2
        MOVE.L  -4(A6),D3
        JSR     fp_add
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        JSR     fp_mul
        JSR     fp_sqrt
        MOVE.L  D0,D2
        MOVE.L  D1,D3
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        JSR     fp_div
        BSR     rt_atn
        UNLK    A6
        RTS
.err:   MOVEQ   #67,D0                  ; asin/acos error
        JSR     rt_error
        MOVEQ   #0,D0
        MOVEQ   #0,D1
        UNLK    A6
        RTS

; D0:D1 = x -> ACOS(x); |x| > 1: error 67
rt_acos:
        LINK    A6,#-16
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        AND.L   #$7FFFFFFF,D0
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  rt_math__c_one,D2
        MOVE.L  rt_math__c_one+4,D3
        JSR     fp_cmp
        TST.L   D0
        BGT     .err
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  rt_math__c_half,D2
        MOVE.L  rt_math__c_half+4,D3
        JSR     fp_cmp
        TST.L   D0
        BGT     .half
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        BSR     rt_asin
        MOVE.L  D0,D2
        MOVE.L  D1,D3
        MOVE.L  rt_math__c_pio2,D0
        MOVE.L  rt_math__c_pio2+4,D1
        JSR     fp_sub
        UNLK    A6
        RTS
.half:
        MOVE.L  rt_math__c_one,D0
        MOVE.L  rt_math__c_one+4,D1
        MOVE.L  -16(A6),D2
        MOVE.L  -12(A6),D3
        JSR     fp_sub
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        MOVE.L  -16(A6),D0
        MOVE.L  -12(A6),D1
        MOVE.L  rt_math__c_half,D2
        MOVE.L  rt_math__c_half+4,D3
        JSR     fp_mul
        MOVE.L  D0,-16(A6)
        MOVE.L  D1,-12(A6)
        JSR     fp_sqrt
        BSR     rt_asin
        MOVE.L  rt_math__c_two,D2
        MOVE.L  rt_math__c_two+4,D3
        JSR     fp_mul
        TST.L   -8(A6)
        BPL     .out
        MOVE.L  D0,D2
        MOVE.L  D1,D3
        MOVE.L  rt_math__c_pi,D0
        MOVE.L  rt_math__c_pi+4,D1
        JSR     fp_sub
.out:
        UNLK    A6
        RTS
.err:   MOVEQ   #67,D0                  ; asin/acos error
        JSR     rt_error
        MOVEQ   #0,D0
        MOVEQ   #0,D1
        UNLK    A6
        RTS

; D0:D1 = x, D2:D3 = y (not an integer) -> x^y = EXP(y*LOG(x)); 0^y: 0, y < 0 error 0
rt_powf:
        LINK    A6,#-8
        MOVE.L  D0,-8(A6)
        MOVE.L  D1,-4(A6)
        AND.L   #$7FF00000,D0           ; x zero (exponent field 0)?
        BNE     .nz
        MOVE.L  D2,D0                   ; y < 0 (not zero): divide by zero
        AND.L   #$7FF00000,D0
        BEQ     .zero
        TST.L   D2
        BPL     .zero
        MOVEQ   #0,D0                   ; divide by zero
        JSR     rt_error
.zero:  MOVEQ   #0,D0
        MOVEQ   #0,D1
        UNLK    A6
        RTS
.nz:    MOVEM.L D2-D3,-(SP)
        MOVE.L  -8(A6),D0
        MOVE.L  -4(A6),D1
        JSR     rt_log
        MOVEM.L (SP)+,D2-D3
        EXG     D0,D2
        EXG     D1,D3
        JSR     fp_mul
        BSR     rt_exp
        UNLK    A6
        RTS

; D0:D1 = x -> DEG(x) = x*180/PI
rt_deg:
        MOVE.L  rt_math__c_d180,D2
        MOVE.L  rt_math__c_d180+4,D3
        JSR     fp_mul
        MOVE.L  rt_math__c_pi,D2
        MOVE.L  rt_math__c_pi+4,D3
        JMP     fp_div

; D0:D1 = x -> RAD(x) = x*PI/180
rt_rad:
        MOVE.L  rt_math__c_pi,D2
        MOVE.L  rt_math__c_pi+4,D3
        JSR     fp_mul
        MOVE.L  rt_math__c_d180,D2
        MOVE.L  rt_math__c_d180+4,D3
        JMP     fp_div

